import xlrd, os, io, traceback
d='tests/samples'
log=io.StringIO()
for f in sorted(os.listdir(d)):
    if not f.endswith('.xls'): continue
    for fi in (False, True):
        try:
            bk = xlrd.open_workbook(os.path.join(d,f), formatting_info=fi, logfile=log)
        except Exception as e:
            continue
        for sh in bk.sheets():
            try:
                for r in range(sh.nrows):
                    sh.row(r); sh.row_values(r); sh.row_types(r); sh.row_slice(r); sh.row_len(r)
                    for c in range(sh.row_len(r)):
                        sh.cell(r,c); sh.cell_value(r,c); sh.cell_type(r,c)
                        if fi: sh.cell_xf_index(r,c)
                for c in range(sh.ncols):
                    sh.col(c); sh.col_values(c); sh.col_types(c); sh.col_slice(c)
                list(sh.get_rows()); list(iter(sh))
                if sh.nrows and sh.ncols: sh[0]; sh[0,0]
                assert isinstance(sh.merged_cells, list)
                sh.cached_page_break_preview_mag_factor; sh.cached_normal_view_mag_factor
            except Exception as e:
                print('FAIL', f, fi, sh.name, type(e).__name__, e)
print('sweep done')
